from collections import deque
from typing import List

def process_balls_sequence(A: List[int]) -> int:
    sequence = deque()

    for exponent in A:
        current_ball_size = 2 ** exponent
        sequence.append(current_ball_size)

        while len(sequence) >= 2 and sequence[-1] == sequence[-2]:
            last_ball_size = sequence.pop()
            sequence.pop()
            new_ball_size = last_ball_size * 2
            sequence.append(new_ball_size)

    return len(sequence)
